SELECT [101_Object_List_qry].Name, [101_Object_List_qry].TypeName, [101_Object_List_qry].Description, [101_Object_List_qry].DateUpdate, DateAdd("d",7-Weekday([DateUpdate])+1,DateAdd("d",-7,[DateUpdate])) AS PreviousWeekEnding, DateAdd("d",7-Weekday([DateUpdate])+1,[DateUpdate]) AS WeekEnding, DatePart("yyyy",[DateUpdate]) AS [Year], DatePart("q",[DateUpdate]) AS Quarter, DatePart("m",[DateUpdate]) AS [Month], DatePart("y",[DateUpdate]) AS [Day of Year], DatePart("ww",[DateUpdate]) AS Week, Format([DateUpdate],"dddd"", ""mmm d yyyy") AS [Long Day], DatePart("d",[DateUpdate]) AS [Day], DatePart("w",[DateUpdate]) AS [Day of the Week], Format([DateUpdate],"Short Time") AS Time2, TimeValue([DateUpdate]) AS [Time], DatePart("h",[DateUpdate]) AS [Hour], DatePart("n",[DateUpdate]) AS [Minute], DatePart("s",[DateUpdate]) AS [Second]
FROM 101_Object_List_qry;

